package com.chatlockdisabler;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

/**
 * Settings for the Chat Lock Disabler plugin.
 */
@ConfigGroup(ChatLockDisablerConfig.GROUP)
public interface ChatLockDisablerConfig extends Config
{
	String GROUP = "chatlockdisabler";

	/**
	 * Whether to replace the game's lock confirmation message.
	 *
	 * @return true to show a "lock blocked" note instead of the game's message
	 */
	@ConfigItem(
		keyName = "replaceLockMessage",
		name = "Replace lock message",
		description = "Replace the game's \"Your chatbox mode is now set to...\" message with a note that the lock was blocked",
		position = 0
	)
	default boolean replaceLockMessage()
	{
		return true;
	}
}

package com.chatlockdisabler;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ScriptID;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.VarClientIntChanged;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.vars.InputType;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.util.Text;

/**
 * Keeps the chatbox mode (the lock set by /@f, /@c, /@gc, /@g) on public chat.
 *
 * <p>The game's send script only consults the mode for un-prefixed messages typed on the
 * All/Public tab. Sends from the Channel, Clan and Group tabs, and the /, //, ///, /g prefixes,
 * pick their channel explicitly, so they keep working with the mode pinned to public.
 */
@Slf4j
@PluginDescriptor(
	name = "Chat Lock Disabler",
	description = "Stops /@ chat mode locks so plain messages always go to public chat",
	tags = {"chat", "mode", "lock", "public", "clan", "channel", "group", "prefix"}
)
public class ChatLockDisablerPlugin extends Plugin
{
	static final int PUBLIC_MODE = 0;
	static final String LOCK_MESSAGE_PREFIX = "Your chatbox mode is now set to ";
	static final String BLOCKED_MESSAGE = "Chat mode lock blocked. Plain messages stay in public chat; "
		+ "use the chat tabs or / prefixes for other channels.";

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ChatLockDisablerConfig config;

	/**
	 * Cleared on shutdown so a reset queued just before the plugin was turned off does nothing.
	 * Written off the client thread by startUp/shutDown, hence volatile.
	 */
	private volatile boolean active;

	/**
	 * Set when the plugin starts or a session (re)starts; the next game tick checks the mode.
	 * The first tick comes after login has finished loading saved client state and building the
	 * chatbox, so a lock restored at login is caught even if no VarClientIntChanged is posted.
	 */
	private volatile boolean checkOnNextTick;

	/** Client thread only. */
	private boolean resetQueued;

	/**
	 * Provides the plugin's config.
	 *
	 * @param configManager RuneLite config manager
	 * @return the config proxy
	 */
	@Provides
	ChatLockDisablerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ChatLockDisablerConfig.class);
	}

	@Override
	protected void startUp()
	{
		active = true;
		checkOnNextTick = true;
	}

	@Override
	protected void shutDown()
	{
		active = false;
		checkOnNextTick = false;
	}

	/**
	 * Arms the post-login check when a new session starts. Region loads (LOADING to LOGGED_IN)
	 * keep the same session and client state, so they are ignored.
	 *
	 * @param event the game state change
	 */
	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING)
		{
			checkOnNextTick = true;
		}
	}

	/**
	 * Runs the pending post-login or startup check.
	 *
	 * @param event the game tick
	 */
	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (checkOnNextTick)
		{
			checkOnNextTick = false;
			resetChatMode();
		}
	}

	/**
	 * Queues a reset whenever something sets the chatbox mode away from public.
	 *
	 * @param event the client variable change
	 */
	@Subscribe
	public void onVarClientIntChanged(VarClientIntChanged event)
	{
		if (event.getIndex() == VarClientID.CHATBOX_MODE
			&& client.getVarcIntValue(VarClientID.CHATBOX_MODE) != PUBLIC_MODE)
		{
			queueReset();
		}
	}

	/**
	 * Replaces the game's lock confirmation with a note that the lock was blocked.
	 *
	 * @param event the chat message
	 */
	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() == ChatMessageType.GAMEMESSAGE
			&& config.replaceLockMessage()
			&& isLockMessage(event.getMessage()))
		{
			event.getMessageNode().setValue(BLOCKED_MESSAGE);
			client.refreshChat();
		}
	}

	static boolean isLockMessage(String message)
	{
		return message != null && Text.removeTags(message).startsWith(LOCK_MESSAGE_PREFIX);
	}

	/**
	 * Resets on a later client-thread pass rather than inside the event. The mode is set
	 * mid-way through the send script, so resetting immediately would reroute the message
	 * that carried the /@ command; deferring lets that one message reach its channel.
	 */
	private void queueReset()
	{
		if (resetQueued)
		{
			return;
		}

		resetQueued = true;
		clientThread.invokeLater(() ->
		{
			resetQueued = false;
			if (active)
			{
				resetChatMode();
			}
		});
	}

	private void resetChatMode()
	{
		int mode = client.getVarcIntValue(VarClientID.CHATBOX_MODE);
		if (mode == PUBLIC_MODE)
		{
			return;
		}

		log.debug("Resetting chatbox mode {} to public", mode);
		client.setVarcIntValue(VarClientID.CHATBOX_MODE, PUBLIC_MODE);

		// Redraw the chat input line so it drops the "(clan)"-style channel label. Skip it while
		// a dialog input (bank search, PM, etc.) owns the chatbox, since the line is rebuilt when
		// that closes, and while the chatbox isn't built yet, since the script would fail.
		if (client.getGameState() == GameState.LOGGED_IN
			&& client.getVarcIntValue(VarClientID.MESLAYERMODE) == InputType.NONE.getType()
			&& client.getWidget(InterfaceID.Chatbox.INPUT) != null)
		{
			client.runScript(ScriptID.CHAT_PROMPT_INIT);
		}
	}
}

package com.chatlockdisabler;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

/**
 * Launches a RuneLite client with this plugin loaded, for local development.
 */
public class ChatLockDisablerPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(ChatLockDisablerPlugin.class);
		RuneLite.main(args);
	}
}

package com.chatlockdisabler;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.google.inject.Guice;
import java.lang.reflect.Proxy;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Queue;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.MessageNode;
import net.runelite.api.ScriptID;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.VarClientIntChanged;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import org.junit.Before;
import org.junit.Test;

/**
 * Exercises the plugin against hand-rolled fakes (JDK proxies), so the tests need no
 * dependencies beyond JUnit and the RuneLite client.
 */
public class ChatModeResetTest
{
	private static final int CLAN_MODE = 2;
	private static final String GAME_LOCK_MESSAGE =
		"Your chatbox mode is now set to Clan chat. To reset your mode, type <col=ef1020>/@p</col>.";

	private final Map<Integer, Integer> varcs = new HashMap<>();
	private final List<Integer> scriptsRun = new ArrayList<>();
	private final Queue<Runnable> clientThreadQueue = new ArrayDeque<>();
	private GameState gameState;
	private boolean chatboxBuilt;
	private boolean replaceLockMessage;
	private int chatRefreshes;

	private ChatLockDisablerPlugin plugin;

	@Before
	public void setUp()
	{
		gameState = GameState.LOGGED_IN;
		chatboxBuilt = true;
		replaceLockMessage = true;

		Client client = fake(Client.class, (method, args) ->
		{
			switch (method)
			{
				case "getVarcIntValue":
					return varcs.getOrDefault((Integer) args[0], 0);
				case "setVarcIntValue":
					varcs.put((Integer) args[0], (Integer) args[1]);
					return null;
				case "getGameState":
					return gameState;
				case "getWidget":
					return chatboxBuilt && (Integer) args[0] == InterfaceID.Chatbox.INPUT
						? fake(Widget.class, (m, a) -> null) : null;
				case "runScript":
					scriptsRun.add((Integer) ((Object[]) args[0])[0]);
					return null;
				case "refreshChat":
					chatRefreshes++;
					return null;
				default:
					return null;
			}
		});

		ClientThread clientThread = new ClientThread()
		{
			@Override
			public void invokeLater(Runnable r)
			{
				clientThreadQueue.add(r);
			}
		};

		ChatLockDisablerConfig config = new ChatLockDisablerConfig()
		{
			@Override
			public boolean replaceLockMessage()
			{
				return replaceLockMessage;
			}
		};

		plugin = Guice.createInjector(binder ->
		{
			binder.bind(Client.class).toInstance(client);
			binder.bind(ClientThread.class).toInstance(clientThread);
			binder.bind(ChatLockDisablerConfig.class).toInstance(config);
		}).getInstance(ChatLockDisablerPlugin.class);

		plugin.startUp();
		tick(); // consume the startup check so each test starts from a settled state
	}

	@Test
	public void lockIsClearedOnlyAfterTheSendThatSetItFinishes()
	{
		setLock(CLAN_MODE);

		// Still locked while the send script that set it is running, so "/@c hi" reaches clan.
		assertEquals(CLAN_MODE, mode());

		drainClientThread();
		assertEquals(ChatLockDisablerPlugin.PUBLIC_MODE, mode());
		assertEquals(List.of(ScriptID.CHAT_PROMPT_INIT), scriptsRun);
	}

	@Test
	public void repeatedChangesQueueOneReset()
	{
		setLock(CLAN_MODE);
		setLock(4);

		assertEquals(1, clientThreadQueue.size());
		drainClientThread();
		assertEquals(ChatLockDisablerPlugin.PUBLIC_MODE, mode());
	}

	@Test
	public void changesToPublicOrOtherVarcsQueueNothing()
	{
		setLock(ChatLockDisablerPlugin.PUBLIC_MODE);
		varcs.put(VarClientID.MESLAYERMODE, 3);
		plugin.onVarClientIntChanged(new VarClientIntChanged(VarClientID.MESLAYERMODE));

		assertTrue(clientThreadQueue.isEmpty());
	}

	@Test
	public void resetQueuedBeforeShutdownDoesNothing()
	{
		setLock(CLAN_MODE);
		plugin.shutDown();
		drainClientThread();

		assertEquals(CLAN_MODE, mode());
		assertTrue(scriptsRun.isEmpty());
	}

	@Test
	public void restartAfterShutdownStillQueuesResets()
	{
		setLock(CLAN_MODE);
		plugin.shutDown();
		drainClientThread();

		plugin.startUp();
		setLock(4);
		drainClientThread();

		assertEquals(ChatLockDisablerPlugin.PUBLIC_MODE, mode());
	}

	@Test
	public void startupClearsExistingLockOnFirstTickOnly()
	{
		plugin.shutDown();
		varcs.put(VarClientID.CHATBOX_MODE, CLAN_MODE);
		plugin.startUp();

		tick();
		assertEquals(ChatLockDisablerPlugin.PUBLIC_MODE, mode());

		// A lock that appears later without an event isn't polled for every tick.
		varcs.put(VarClientID.CHATBOX_MODE, CLAN_MODE);
		tick();
		assertEquals(CLAN_MODE, mode());
	}

	@Test
	public void loginClearsLockRestoredWithoutAnEvent()
	{
		gameStateChanged(GameState.LOGIN_SCREEN);
		gameStateChanged(GameState.LOGGING_IN);
		varcs.put(VarClientID.CHATBOX_MODE, CLAN_MODE);
		gameStateChanged(GameState.LOGGED_IN);

		tick();
		assertEquals(ChatLockDisablerPlugin.PUBLIC_MODE, mode());
	}

	@Test
	public void worldHopArmsTheCheck()
	{
		gameStateChanged(GameState.HOPPING);
		varcs.put(VarClientID.CHATBOX_MODE, CLAN_MODE);
		gameStateChanged(GameState.LOGGED_IN);

		tick();
		assertEquals(ChatLockDisablerPlugin.PUBLIC_MODE, mode());
	}

	@Test
	public void regionLoadDoesNotArmTheCheck()
	{
		gameStateChanged(GameState.LOADING);
		varcs.put(VarClientID.CHATBOX_MODE, CLAN_MODE);
		gameStateChanged(GameState.LOGGED_IN);

		tick();
		assertEquals(CLAN_MODE, mode());
	}

	@Test
	public void promptNotRedrawnBeforeChatboxIsBuilt()
	{
		chatboxBuilt = false;
		setLock(CLAN_MODE);
		drainClientThread();

		assertEquals(ChatLockDisablerPlugin.PUBLIC_MODE, mode());
		assertTrue(scriptsRun.isEmpty());
	}

	@Test
	public void promptNotRedrawnWhileDialogInputIsOpen()
	{
		varcs.put(VarClientID.MESLAYERMODE, 3);
		setLock(CLAN_MODE);
		drainClientThread();

		assertEquals(ChatLockDisablerPlugin.PUBLIC_MODE, mode());
		assertTrue(scriptsRun.isEmpty());
	}

	@Test
	public void promptNotRedrawnWhileLoggingIn()
	{
		gameState = GameState.LOGGING_IN;
		setLock(CLAN_MODE);
		drainClientThread();

		assertEquals(ChatLockDisablerPlugin.PUBLIC_MODE, mode());
		assertTrue(scriptsRun.isEmpty());
	}

	@Test
	public void lockMessageIsReplaced()
	{
		String[] value = new String[1];
		plugin.onChatMessage(chatMessage(ChatMessageType.GAMEMESSAGE, GAME_LOCK_MESSAGE, value));

		assertEquals(ChatLockDisablerPlugin.BLOCKED_MESSAGE, value[0]);
		assertEquals(1, chatRefreshes);
	}

	@Test
	public void lockMessageKeptWhenReplacementDisabled()
	{
		replaceLockMessage = false;
		String[] value = new String[1];
		plugin.onChatMessage(chatMessage(ChatMessageType.GAMEMESSAGE, GAME_LOCK_MESSAGE, value));

		assertNull(value[0]);
		assertEquals(0, chatRefreshes);
	}

	@Test
	public void playerMessagesQuotingTheLockTextAreUntouched()
	{
		String[] value = new String[1];
		plugin.onChatMessage(chatMessage(ChatMessageType.PUBLICCHAT, GAME_LOCK_MESSAGE, value));

		assertNull(value[0]);
	}

	private void setLock(int newMode)
	{
		varcs.put(VarClientID.CHATBOX_MODE, newMode);
		plugin.onVarClientIntChanged(new VarClientIntChanged(VarClientID.CHATBOX_MODE));
	}

	private int mode()
	{
		return varcs.getOrDefault(VarClientID.CHATBOX_MODE, 0);
	}

	private void tick()
	{
		plugin.onGameTick(new GameTick());
	}

	private void gameStateChanged(GameState state)
	{
		gameState = state;
		GameStateChanged event = new GameStateChanged();
		event.setGameState(state);
		plugin.onGameStateChanged(event);
	}

	private void drainClientThread()
	{
		Runnable r;
		while ((r = clientThreadQueue.poll()) != null)
		{
			r.run();
		}
	}

	private static ChatMessage chatMessage(ChatMessageType type, String message, String[] valueOut)
	{
		MessageNode node = fake(MessageNode.class, (method, args) ->
		{
			if ("setValue".equals(method))
			{
				valueOut[0] = (String) args[0];
			}
			return null;
		});
		return new ChatMessage(node, type, "", message, null, 0);
	}

	private interface Handler
	{
		Object handle(String method, Object[] args);
	}

	/**
	 * Builds a proxy that routes calls to the handler, returning zero/false for unhandled
	 * primitive methods so callers don't hit null unboxing.
	 */
	private static <T> T fake(Class<T> type, Handler handler)
	{
		Object proxy = Proxy.newProxyInstance(type.getClassLoader(), new Class<?>[]{type}, (self, method, args) ->
		{
			Object result = handler.handle(method.getName(), args == null ? new Object[0] : args);
			if (result != null || !method.getReturnType().isPrimitive())
			{
				return result;
			}
			Class<?> rt = method.getReturnType();
			if (rt == boolean.class)
			{
				return false;
			}
			if (rt == void.class)
			{
				return null;
			}
			if (rt == long.class)
			{
				return 0L;
			}
			if (rt == float.class)
			{
				return 0f;
			}
			if (rt == double.class)
			{
				return 0d;
			}
			if (rt == char.class)
			{
				return '\0';
			}
			if (rt == byte.class)
			{
				return (byte) 0;
			}
			if (rt == short.class)
			{
				return (short) 0;
			}
			return 0;
		});
		return type.cast(proxy);
	}
}

package com.chatlockdisabler;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class LockMessageTest
{
	@Test
	public void matchesGameLockMessage()
	{
		assertTrue(ChatLockDisablerPlugin.isLockMessage(
			"Your chatbox mode is now set to Clan chat. To reset your mode, type <col=ef1020>/@p</col>."));
	}

	@Test
	public void ignoresOtherMessages()
	{
		assertFalse(ChatLockDisablerPlugin.isLockMessage("Your chatbox mode has been reset to Public chat."));
		assertFalse(ChatLockDisablerPlugin.isLockMessage("Welcome to Old School RuneScape."));
		assertFalse(ChatLockDisablerPlugin.isLockMessage(null));
	}
}
